// Category A — behavior borrowed from react-aria-components, look (.sd-textfield*) owned in src.
// Compound component: owns multiple parts (Label/Input/Description/Error) as BEM subclasses.
// (Contract: docs/rules/component-contract.md — sd- prefix, single class, data-*, tokens only)
import {
  TextField as AriaTextField,
  Group,
  Label,
  Input,
  Text,
  FieldError,
} from "react-aria-components";
import type {
  TextFieldProps as AriaTextFieldProps,
  ValidationResult,
} from "react-aria-components";
import { useState } from "react";
import type { ReactNode, Ref } from "react";
import { roleSize, type ControlSize } from "./controlSize";
import "./TextField.css";

type FieldSize = ControlSize;
type TextFieldVariant = "outline" | "underline";

export interface TextFieldProps extends Omit<AriaTextFieldProps, "className" | "children"> {
  /**
   * Visual variant. `outline` draws the bordered box; `underline` draws no box, only a rule under
   * the value, as on a counter, a POS or a kiosk.
   *
   * @default "outline"
   */
  variant?: TextFieldVariant;
  /**
   * Size axis. Changes input height/padding/font.
   *
   * @default "medium"
   */
  size?: FieldSize;
  /** Field label. */
  label?: string;
  /**
   * A `ContextualHelp` shown after the label, for a note the reader opens when they need it rather
   * than a `description` that is always on screen.
   */
  contextualHelp?: ReactNode;
  /** Supporting description below the input. */
  description?: string;
  /** Message shown when validation fails (visible in the isInvalid state). */
  errorMessage?: string | ((v: ValidationResult) => string);
  /** input placeholder. */
  placeholder?: string;
  /**
   * Content before the value, inside the field: a flag, a currency sign, an icon. Muted ink.
   * It is NOT announced with the value: a screen reader reads the label and the value only, so
   * anything that changes what the value means must also be in the `label`. Decorative content
   * should carry `aria-hidden`.
   */
  leading?: ReactNode;
  /**
   * Content after the value, inside the field: a unit (원, %), a clear or visibility Button. Muted
   * ink for text; an interactive control brings its own ink and its own accessible name. Like
   * `leading` it is not announced with the value, so a unit that matters belongs in the `label` too
   * ("Amount (원)").
   */
  trailing?: ReactNode;
  /** Additional class (optional). sd-textfield is always preserved. */
  className?: string;
  /** Forwarded to the underlying <input> DOM node. */
  ref?: Ref<HTMLInputElement>;
}

export function TextField({
  variant = "outline",
  size = "medium",
  label,
  contextualHelp,
  description,
  errorMessage,
  placeholder,
  leading,
  trailing,
  className,
  ref,
  ...props
}: TextFieldProps) {
  // The box's focus indicator follows the INPUT's focus, relayed onto the group as
  // `data-input-focused`: `focus-within` would also light the whole field when an interactive
  // `trailing` Button takes focus, beside that Button's own ring. Read through React Aria's
  // `onFocusChange` (its useFocus), which also clears when the field is disabled while focused,
  // where a raw React `onBlur` never fires.
  const [isInputFocused, setInputFocused] = useState(false);
  return (
    <AriaTextField
      {...props}
      onFocusChange={(isFocused) => {
        setInputFocused(isFocused);
        props.onFocusChange?.(isFocused);
      }}
      data-variant={variant}
      className={className ? `sd-textfield ${className}` : "sd-textfield"}
    >
      {({ isDisabled, isInvalid }) => (
        <>
          {contextualHelp ? (
            <div className="sd-textfield__label-group">
              {label && <Label className={`sd-textfield__label sd-type-label-${roleSize(size)}`}>{label}</Label>}
              {contextualHelp}
            </div>
          ) : (
            label && <Label className={`sd-textfield__label sd-type-label-${roleSize(size)}`}>{label}</Label>
          )}
          {/* The Group is the field's box (border, corner, focus ring), so `leading` and `trailing`
              can sit inside it beside the input: the SearchField / NumberField pattern. RAC's
              TextField puts no state on the Group, so disabled and invalid (including invalid from
              validation, not just the prop) are relayed from the field's render props. */}
          <Group
            data-size={size}
            data-variant={variant}
            isDisabled={isDisabled}
            isInvalid={isInvalid}
            data-input-focused={isInputFocused || undefined}
            className="sd-textfield__group"
          >
            {leading != null && <span className="sd-textfield__leading">{leading}</span>}
            <Input
              ref={ref}
              placeholder={placeholder}
              data-leading={leading != null || undefined}
              data-trailing={trailing != null || undefined}
              className={`sd-textfield__input sd-type-body-${roleSize(size)}`}
            />
            {trailing != null && <span className="sd-textfield__trailing">{trailing}</span>}
          </Group>
          {description && (
            <Text slot="description" className={`sd-textfield__description sd-type-caption-${roleSize(size)}`}>
              {description}
            </Text>
          )}
          <FieldError className={`sd-textfield__error sd-type-caption-${roleSize(size)}`}>{errorMessage}</FieldError>
        </>
      )}
    </AriaTextField>
  );
}

/* TextField.css — .sd-textfield (+ BEM 서브파트)
   규칙: sd- 프리픽스 / 각 파트는 평평한 단일 클래스(하위결합자 없음) /
        상태는 같은 요소의 data-*(react-aria가 부여) / Cmp 토큰만 참조. */
.sd-textfield {
  /* react-aria puts [data-readonly] on the ROOT, not the group — route the group's
     background through a local -current var (contract §6.5) so the child can react
     without a descendant combinator. Default = the normal editable background. */
  --sd-textfield-group-background-current: var(--sd-textfield-group-background);
  display: flex;
  flex-direction: column;
  gap: var(--sd-textfield-gap);
}
/* readonly: muted fill signals "not editable"; text stays selectable so cursor is unchanged. */
.sd-textfield[data-readonly] {
  --sd-textfield-group-background-current: var(--sd-textfield-group-background-readonly);
}
/* underline — no box, only the rule under the value: no corner, and the border on the block-end side
   alone. The fill (transparent, or the readonly cue) is decided on the root and the inline inset is
   the text line's, both relayed. Focus keeps the field's own ring construct (contract §6.7). */
.sd-textfield[data-variant="underline"] {
  --sd-textfield-group-background-current: var(--sd-textfield-group-background-underline);
}
.sd-textfield[data-variant="underline"][data-readonly] {
  --sd-textfield-group-background-current: var(--sd-textfield-group-background-readonly);
}

/* label-group — present only with `contextualHelp`: the label and its help trigger share one row. */
.sd-textfield__label-group {
  display: flex;
  align-items: center;
  gap: var(--sd-textfield-label-group-gap);
}

.sd-textfield__label {
  padding-inline: var(--sd-textfield-text-padding-inline);
  color: var(--sd-textfield-label-foreground);
}

/* group — the field's box: border, corner, fill and focus ring, with the input and the optional
   `leading` / `trailing` slots in one row inside it (the SearchField / NumberField pattern). RAC
   emits data-hovered / data-disabled / data-invalid on it; data-input-focused is the input's own
   focus, relayed by the tsx so an interactive slot taking focus does not light the whole box. */
.sd-textfield__group {
  --sd-textfield-group-radius-current: var(--sd-textfield-group-radius-medium);
  display: flex;
  align-items: center;
  gap: var(--sd-textfield-group-gap);
  width: 100%;
  background: var(--sd-textfield-group-background-current);
  border: var(--sd-textfield-group-border-width) solid var(--sd-textfield-group-border);
  border-radius: var(--sd-textfield-group-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  transition:
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
}
/* The inline inset is relayed, not padded on the group: it is spent by the input (or by the slot at
   that end), so the whole width up to the box edge is the input's to click, as before the slots. */
.sd-textfield__group[data-size="x-small"] {
  --sd-textfield-group-radius-current: var(--sd-textfield-group-radius-x-small);
  --sd-textfield-inset-current: var(--sd-textfield-group-padding-inline-x-small);
  min-height: var(--sd-textfield-group-height-x-small);
}
.sd-textfield__group[data-size="small"] {
  --sd-textfield-group-radius-current: var(--sd-textfield-group-radius-small);
  --sd-textfield-inset-current: var(--sd-textfield-group-padding-inline-small);
  min-height: var(--sd-textfield-group-height-small);
}
.sd-textfield__group[data-size="medium"] {
  --sd-textfield-group-radius-current: var(--sd-textfield-group-radius-medium);
  --sd-textfield-inset-current: var(--sd-textfield-group-padding-inline-medium);
  min-height: var(--sd-textfield-group-height-medium);
}
.sd-textfield__group[data-size="large"] {
  --sd-textfield-group-radius-current: var(--sd-textfield-group-radius-large);
  --sd-textfield-inset-current: var(--sd-textfield-group-padding-inline-large);
  min-height: var(--sd-textfield-group-height-large);
}
.sd-textfield__group[data-size="x-large"] {
  --sd-textfield-group-radius-current: var(--sd-textfield-group-radius-x-large);
  --sd-textfield-inset-current: var(--sd-textfield-group-padding-inline-x-large);
  min-height: var(--sd-textfield-group-height-x-large);
}
.sd-textfield__group[data-hovered] {
  border-color: var(--sd-textfield-group-border-hover);
}
.sd-textfield__group[data-input-focused] {
  border-color: var(--sd-textfield-group-border-focus);
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-textfield__group[data-invalid] {
  border-color: var(--sd-textfield-group-border-invalid);
}
.sd-textfield__group[data-invalid][data-input-focused] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-textfield-group-border-invalid) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-textfield__group[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

/* underline — no box, only the rule under the value: transparent fill, no corner, no inline inset,
   and the border on the block-end side alone. Focus keeps the field's own ring construct, so the
   indicator is the same one every field uses (contract §6.7), drawn around a box that is now just
   the rule's row. After the size and state rules, which it overrides at equal or lower specificity. */
.sd-textfield__group[data-variant="underline"] {
  --sd-textfield-inset-current: var(--sd-textfield-group-padding-inline-underline);
  border-width: 0 0 var(--sd-textfield-group-border-width);
  /* no box, so no corner: 0 rather than a token, since no radius rung means "none" */
  border-radius: 0;
}

/* input — the text itself, borderless inside the group, which owns the box. */
.sd-textfield__input {
  flex: 1;
  min-width: 0;
  /* A value wider than the field ends in an ellipsis while it rests, not at a hard clip mid-glyph;
     focused, the input scrolls to the caret as it always has. */
  text-overflow: ellipsis;
  align-self: stretch;
  padding-block: 0;
  padding-inline: var(--sd-textfield-inset-current);
  background: transparent;
  color: var(--sd-textfield-input-foreground);
  border: 0;
  /* Suppress the UA focus outline — the group draws the field's indicator
     (`[data-input-focused]`, relayed from this input: border-colour + ring). Without this the browser stacks `outline: auto`
     inside that ring, in the OS accent colour (contract §6 rule 3). */
  outline: none;
}
/* a slot at an end spends that end's inset instead of the input */
.sd-textfield__input[data-leading] {
  padding-inline-start: 0;
}
.sd-textfield__input[data-trailing] {
  padding-inline-end: 0;
}
.sd-textfield__input::placeholder {
  color: var(--sd-textfield-input-placeholder);
}

/* leading / trailing — supporting content in the row, never shrunk by a long value. */
.sd-textfield__leading,
.sd-textfield__trailing {
  display: inline-flex;
  flex: none;
  align-items: center;
}
.sd-textfield__leading {
  padding-inline-start: var(--sd-textfield-inset-current);
  color: var(--sd-textfield-leading-foreground);
}
.sd-textfield__trailing {
  padding-inline-end: var(--sd-textfield-inset-current);
  color: var(--sd-textfield-trailing-foreground);
}

/* description / error */
.sd-textfield__description {
  padding-inline: var(--sd-textfield-text-padding-inline);
  color: var(--sd-textfield-description-foreground);
}
.sd-textfield__error {
  padding-inline: var(--sd-textfield-text-padding-inline);
  color: var(--sd-textfield-error-foreground);
}
